uniform float speed : 0.0 .. 3.0 = 0.4;
uniform float swell_count : 0.5 .. 4.0 = 1.5;
uniform float swell_width : 0.05 .. 0.3 = 0.12;
uniform float foam_intensity : 0.0 .. 1.0 = 0.3;
uniform vec3 deep_color : color = 0.02, 0.08, 0.25;
uniform vec3 swell_color : color = 0.1, 0.35, 0.6;
uniform vec3 foam_color : color = 0.6, 0.8, 1.0;
uniform float shimmer_speed : 0.0 .. 2.0 = 0.6;
uniform float shimmer_strength : 0.0 .. 0.5 = 0.15;

state float swell_ph;
state float shimmer_ph;

void update() {
  swell_ph = fract(swell_ph + dt * speed);
  shimmer_ph = fract(shimmer_ph + dt * shimmer_speed);
}

vec3 shade(Led led) {
  float y_norm = (led.pos.y + 0.15) / 0.3;
  float swell_phase = fract(y_norm * swell_count - swell_ph);
  float swell = smoothstep(swell_width, 0.0, abs(swell_phase - 0.5));

  float shimmer = sin(led.pos.y * 12.0 + shimmer_ph * 6.2832 + led.pos.x * 8.0) * 0.5 + 0.5;
  shimmer = shimmer * shimmer_strength;

  vec3 base = mix(deep_color, swell_color, swell);
  vec3 foam = foam_color * smoothstep(0.7, 1.0, swell) * (1.0 + shimmer);

  return base + foam;
}
